// Locale and currency formatting. Formatters are created per locale and
// option set and cached, as Intl objects are expensive to construct; their
// inputs (the frozen clock, the fixed locale and currency) make the output
// deterministic.
import { createContext, useContext, useMemo } from "react";
import { useLocale } from "./i18n/I18nProvider.jsx";

const CurrencyContext = createContext({ currency: "EUR" });
const formatters = new Map();

function formatter(kind, locale, options) {
    const key = `${kind}|${locale}|${JSON.stringify(options)}`;
    let result = formatters.get(key);
    if (!result) {
        result = kind === "number" ? new Intl.NumberFormat(locale, options) : new Intl.DateTimeFormat(locale, options);
        formatters.set(key, result);
    }
    return result;
}

export function CurrencyProvider({ currency, children }) {
    const value = useMemo(() => ({ currency }), [currency]);
    return <CurrencyContext.Provider value={value}>{children}</CurrencyContext.Provider>;
}

export function useCurrency() {
    return useContext(CurrencyContext).currency;
}

export function useMoneyFormat({ fractionDigits = 0 } = {}) {
    const { intlLocale } = useLocale();
    const currency = useCurrency();
    return useMemo(() => {
        const format = formatter("number", intlLocale, { style: "currency", currency, maximumFractionDigits: fractionDigits, minimumFractionDigits: fractionDigits });
        return (amount) => format.format(amount);
    }, [intlLocale, currency, fractionDigits]);
}

export function useNumberFormat(options = {}) {
    const { intlLocale } = useLocale();
    const key = JSON.stringify(options);
    return useMemo(() => {
        const format = formatter("number", intlLocale, options);
        return (value) => format.format(value);
    }, [intlLocale, key]);
}

// Formats ISO days ("2026-11-13") in UTC, so the time zone of the machine
// doesn't move them.
export function useDateFormat(options) {
    const { intlLocale } = useLocale();
    const key = JSON.stringify(options);
    return useMemo(() => {
        const format = formatter("date", intlLocale, { ...options, timeZone: "UTC" });
        return (day) => format.format(new Date(`${day}T00:00:00Z`));
    }, [intlLocale, key]);
}
